def construct_maximum_binary_tree(nums):
    stack = []                                    # holds nodes in decreasing value order
    for num in nums:
        node = TreeNode(num)
        last_popped = None
        while stack and stack[-1].val < num:
            last_popped = stack.pop()               # pop everyone smaller
        node.left = last_popped                      # last popped becomes left child
        if stack:
            stack[-1].right = node                    # new node is right child of remaining top
        stack.append(node)
    return stack[0] if stack else None                # bottom of stack is the root

