import java.util.*;

public class Main {
    static TreeNode constructMaximumBinaryTree(int[] nums) {
        Deque<TreeNode> stack = new ArrayDeque<>();            // holds nodes in decreasing value order
        for (int num : nums) {
            TreeNode node = new TreeNode(num);
            TreeNode lastPopped = null;
            while (!stack.isEmpty() && stack.peek().val < num) {
                lastPopped = stack.pop();                        // pop everyone smaller
            }
            node.left = lastPopped;                                // last popped becomes left child
            if (!stack.isEmpty()) stack.peek().right = node;       // new node is right child of remaining top
            stack.push(node);
        }
        TreeNode root = null;
        for (TreeNode n : stack) root = n;                          // bottom of stack is the root
        return root;
    }
}

