struct TreeNode { int val; TreeNode* left; TreeNode* right; TreeNode(int v): val(v), left(nullptr), right(nullptr) {} };

TreeNode* constructMaximumBinaryTree(vector<int>& nums) {
    vector<TreeNode*> stack;                                    // holds nodes in decreasing value order
    for (int num : nums) {
        TreeNode* node = new TreeNode(num);
        TreeNode* lastPopped = nullptr;
        while (!stack.empty() && stack.back()->val < num) {
            lastPopped = stack.back();
            stack.pop_back();                                        // pop everyone smaller
        }
        node->left = lastPopped;                                     // last popped becomes left child
        if (!stack.empty()) stack.back()->right = node;              // new node is right child of remaining top
        stack.push_back(node);
    }
    return stack.empty() ? nullptr : stack.front();                 // bottom of stack is the root
}
